input.script:
services = list_services({})

counts = for s in services.items {
    r = boundary retry 2 {
        return search_logs({ service: s, level: "ERROR" })
    } catch err {
        return fail("LOG_FAIL", err.code + ": " + err.message)
    }
    return { service: s, total: r.total_items, pages: r.total_pages }
}

by_total = list.sort_by(counts, "total", "desc")
top = by_total[0]

npages = if top.pages > 15 {
    return 15
} else {
    return top.pages
}

pages = for p in list.range(1, npages + 1) {
    r = boundary retry 2 {
        return search_logs({ service: top.service, level: "ERROR", page: p })
    } catch err {
        return fail("LOG_FAIL", err.code + ": " + err.message)
    }
    return r.items
}

logs = fold acc = [] for pg in pages {
    return acc + pg
}
times = for l in logs {
    return time.parse(l.ts)
}
n = list.length(times)
assert(n > 0, "no error logs for top service")

limit = if n > 4 {
    return n - 4
} else {
    return 0
}
candidates = for i in list.range(0, limit) {
    skip if times[i + 4] - times[i] > 300000
    return i
}
burst_start = if candidates != [] {
    return times[candidates[0]]
} else {
    return times[0]
}

deploys = boundary retry 2 {
    return get_deploys({ service: top.service })
} catch err {
    return fail("DEPLOY_FAIL", err.code + ": " + err.message)
}
pre = for d in deploys {
    t = time.parse(d.deployed_at)
    skip if t > burst_start
    return { sha: d.sha, t }
}
assert(pre != [], "no deploy precedes the spike")
pre_sorted = list.sort_by(pre, "t", "desc")
chosen = pre_sorted[0]

owner = boundary retry 2 {
    return get_service_owners({ service: top.service })
} catch err {
    return fail("OWNER_FAIL", err.code + ": " + err.message)
}

res = submit_result({ answer: { service: top.service, deploy_sha: chosen.sha, owner_email: owner.owner_email } })
return { submitted: res.recorded, service: top.service, deploy_sha: chosen.sha, owner_email: owner.owner_email, burst_start: time.format(burst_start), error_total: top.total }

